from ute_common_config.config import Config
from ute_common_validator.validator import IsInstance, Or, Assert, ValidLength, And


class PduMixin(Config):
    """This class is defining base validators and functions for testline variants"""
    PDU_TYPES_ALLOWED = ["APC", "SWH", "ATEN", "ATEN24", "DCS", "BBOX", "MOXA", "SHCL", "MYCOMP",
                         "FACOM", "SIMATIC", "EPC", "EPCNC", "PKC", "PKC16", "BBOXPSE", "ICT", "APC16", "FPFH",
                         "HBTE"]
    PROTOCOLS_ALLOWED = ["http", "snmp"]

    def __init__(self):
        super(PduMixin, self).__init__()

    def get_allowed_pdu_outlets(self, pdu):
        """
        :param string      pdu:                 Pdu type to check allowed outlets values
        :return:  list of allowed outlets number
        """
        default_types_outlets = [x for x in range(1, 25)]
        dcs_type_outlets = [x for x in range(11, 17)] + [x for x in range(21, 27)]
        moxa_type_outlets = [x for x in range(1, 7)]
        aten24_type_outlets = [x for x in range(1, 25)]
        epc_type_outlets = [x for x in range(1, 13)]
        epcnc_type_outlets = [x for x in range(1, 13)]
        bboxpse_type_outlets = [x for x in range(1, 5)]
        ict_type_outlets = [x for x in range(1, 12)]
        apc16_type_outlets = [x for x in range(1, 17)]
        pkc16_type_outlets = [x for x in range(1, 17)]
        shcl_type_outlets = [x for x in range(1, 65536)]
        fpfh_type_outlets = [x for x in range(1, 7)]
        mycomp_type_outlets = [x for x in range(1, 9)]
        hbte_type_outlets = [x for x in range(1, 21)]
        pdu_outlets_dict = {'DCS': dcs_type_outlets, 'MOXA': moxa_type_outlets, 'ATEN24': aten24_type_outlets, 'APC16': apc16_type_outlets,
                            'EPC': epc_type_outlets, 'EPCNC': epcnc_type_outlets, 'BBOXPSE': bboxpse_type_outlets, 'ICT': ict_type_outlets,
                            'PKC16': pkc16_type_outlets, 'SHCL': shcl_type_outlets, 'FPFH': fpfh_type_outlets, 'MYCOMP': mycomp_type_outlets,
                            'HBTE': hbte_type_outlets, 'PKC': pkc16_type_outlets}
        return pdu_outlets_dict.setdefault(pdu, default_types_outlets)


class FSMConfig(Config):
    """This class validates vlan id range value and check if none value."""
    def __init__(self):
        super(FSMConfig, self).__init__()

    def vlan_id_validator(self, vlan_ids):
        """
        :param list vlan_ids:   list of vlan ids.
        :return: boolean
        """
        vlan_ids_range_validator = Assert(lambda vlanids: all((vlan_id in range(1, 5000) for vlan_id in vlan_ids)), 'vlan_id not in range 1 to 5000')
        vlan_with_ids_validators = And(IsInstance(list), ValidLength(4, 6), vlan_ids_range_validator, chain=True)
        vlan_id_isnone_validator = Assert(lambda vlanid: vlanid is None, 'vlan_id should be none')
        return Or(vlan_id_isnone_validator, vlan_with_ids_validators)
